def tax_cents(subtotal, tax_percent):
    """Round-half-up tax on ``subtotal`` using exact arithmetic.

    Integer percents use pure integer arithmetic; other exact values
    (e.g. Decimal/Fraction/float percents) are converted without binary
    floating point loss via ``Fraction(str(tax_percent))``.
    """
    if isinstance(tax_percent, int) and not isinstance(tax_percent, bool):
        return (subtotal * tax_percent + 50) // 100
    from fractions import Fraction
    from math import floor
    exact = Fraction(subtotal) * Fraction(str(tax_percent)) / 100
    return int(floor(exact + Fraction(1, 2)))


def calculate(lines, tax_percent):
    subtotal = sum(line['unit_cents'] * line['quantity'] for line in lines)
    return subtotal, tax_cents(subtotal, tax_percent)

