def _round_half_up(numerator, denominator):
    """Round numerator/denominator half up with exact integer arithmetic."""
    return (2 * numerator + denominator) // (2 * denominator)


def calculate(lines, tax_percent):
    """Return (subtotal_cents, tax_cents) for priced lines.

    Each line contributes unit_cents * quantity. Tax is tax_percent of the
    whole subtotal, rounded half up. Input is only read, never mutated.
    """
    subtotal = sum(line['unit_cents'] * line['quantity'] for line in lines)
    return subtotal, _round_half_up(subtotal * tax_percent, 100)

